import { TrafficMonitor } from './monitoring/trafficMonitor';
import { RefactorEngine } from './refactor/refactorEngine';
import { APIMonitorConfig, RefactorConfig, TrafficRecord, PredictionResult, RefactorSuggestion } from './types';

class X2YSdk {
  private trafficMonitor: TrafficMonitor;
  private refactorEngine: RefactorEngine;

  constructor(monitorConfig: APIMonitorConfig = {}, refactorConfig: RefactorConfig = {}) {
    this.trafficMonitor = new TrafficMonitor(monitorConfig);
    this.refactorEngine = new RefactorEngine(refactorConfig);
  }

  recordAPITraffic(data: TrafficRecord): void {
    this.trafficMonitor.record(data);
  }

  async predictAPIIssues(endpoint: string): Promise<PredictionResult> {
    return await this.trafficMonitor.predict(endpoint);
  }

  async refactorCode(code: string): Promise<RefactorSuggestion[]> {
    return await this.refactorEngine.refactorCode(code);
  }

  async refactorFile(filePath: string): Promise<RefactorSuggestion[]> {
    return await this.refactorEngine.refactorFile(filePath);
  }
}

// Use module.exports for CommonJS compatibility with require('x2y-dev-tools-sdk')
module.exports = { X2YSdk };
